# ── GT models and 718/981 (2026-11-04): ranges Porsche prints in its own brochures / press kits.
# Read by research agents from porschecarshistory.com, Wayback copies of files.porsche.com and
# newsroom.porsche.com; verbatim quotes, URLs and edition codes in
# research_notes/Porsche factory colour documents/palettes_gt.md and palettes_718.md.
# Scope key = "<model_line>|<generation>|<variant>" so a range only ever applies to that model.
def _e(key, years, src, basis, solid=(), metallic=(), special=(), notes="", complete=True):
    return {"file": src, "page": "colour page", "label_year": None, "model_year": years[0],
            "my_basis": basis, "complete": complete, "models": [key], "market": "ROW",
            "scopes": [(key, y) for y in years], "notes": notes,
            "tiers": {"solid": [(None, n, "") for n in solid], "metallic": [(None, n, "") for n in metallic],
                      "special": [(None, n, "") for n in special]}}


